package factory_dispatch_coordinator.Factory_Dispatch_Coordinator

import org.sireum._
import art._
import factory_dispatch_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Outcome_Qualification_Api {
  def id: Art.BridgeId
  def raw_outcome_Id : Art.PortId
  def qualified_outcome_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_outcome: Factory_Dispatch_Coordinator.Qualified_Outcome.Type = $

  def put_qualified_outcome(value : Factory_Dispatch_Coordinator.Qualified_Outcome.Type) : Unit = {
    Contract(
      Modifies(qualified_outcome),
      Ensures(
        qualified_outcome == value
      )
    )
    Spec {
      qualified_outcome = value
    }

    Art.putValue(qualified_outcome_Id, Factory_Dispatch_Coordinator.Qualified_Outcome_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Outcome_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val raw_outcome_Id : Art.PortId,
  val qualified_outcome_Id : Art.PortId) extends Outcome_Qualification_Api

@datatype class Outcome_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val raw_outcome_Id : Art.PortId,
  val qualified_outcome_Id : Art.PortId) extends Outcome_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_outcome: Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample = $

  def get_raw_outcome() : Option[Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample] = {
    Contract(
      Ensures(
        Res == Some(raw_outcome)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample] = Art.getValue(raw_outcome_Id) match {
      case Some(Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_outcome.  Expecting 'Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample]()
      case _ => None[Factory_Dispatch_Coordinator.Dispatch_Outcome_Sample]()
    }
    return value
  }
}
